// Builds the Rust constraint solver (wasm/solver) to WebAssembly and embeds it in
// src/core/wasm/solver.wasm.ts as base64, so the core loads it the same way in Node, the page and
// the worker, and CI needs no Rust. Commit the generated file with any change to the Rust.
//   node scripts/build-wasm.ts
import { execFileSync } from "node:child_process";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { delimiter, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = fileURLToPath(new URL("..", import.meta.url));
const crate = join(root, "wasm", "solver");
// rustup installs to ~/.cargo/bin, which may not be on PATH.
const env = { ...process.env, PATH: `${join(homedir(), ".cargo", "bin")}${delimiter}${process.env.PATH ?? ""}` };
execFileSync(process.platform === "win32" ? "cargo.exe" : "cargo", ["build", "--release", "--target", "wasm32-unknown-unknown"], { cwd: crate, env, stdio: "inherit" });
const bytes = readFileSync(join(crate, "target", "wasm32-unknown-unknown", "release", "msb_solver.wasm"));
const out = join(root, "src", "core", "wasm");
mkdirSync(out, { recursive: true });
const b64 = bytes.toString("base64");
const lines = b64.match(/.{1,120}/g) ?? [];
writeFileSync(
  join(out, "solver.wasm.ts"),
  `// Generated by scripts/build-wasm.ts from wasm/solver (Rust). Do not edit.\n` +
    `// ${bytes.length} bytes.\n` +
    // An array, joined: a thousand strings added together nest too deep for the linter's parser.
    `export const SOLVER_WASM_BASE64 = [\n${lines.map((l) => `  "${l}",`).join("\n")}\n].join("");\n`,
);
console.log(`solver.wasm: ${bytes.length} bytes`);
